import {rangePlayback} from "./topic-tools.js";
import {recoveryState,recoveryTrace,harnessMass,redistributeGroup,completionMixture,prefixCapture} from "./agents-model.js";
const fmt=x=>Number(x.toFixed(4)).toString(),pct=x=>fmt(x*100)+"%";
const controls="<div class='dense-actions'><button data-play>Play</button><button data-reset>Replay</button></div>";
const bar=(label,value,color="#bfdff2")=>"<div class='agents-bar'><span>"+label+"</span><div><i style='width:"+Math.min(100,Math.abs(value)*100)+"%;background:"+color+"'></i></div><strong>"+fmt(value)+"</strong></div>";
export function recoveryBody(step=0){
 const m=recoveryState(step);
 return "<ol class='agents-trace'>"+recoveryTrace.map((x,i)=>"<li class='"+(i>step?"agents-future":x.imitate?"agents-target":"agents-context")+"'><span>"+(i+1)+". "+x.actor+"</span><strong>"+x.text+"</strong><small>"+(i>step?"Not yet observed":x.imitate?"Context + supervised target":x.actor==="tool"?"Context only":"Context retained · target masked")+" · "+x.tokens+" tokens</small></li>").join("")+"</ol><p>Observed context: "+m.contextTokens+" tokens. Supervised assistant targets: "+m.targetTokens+". Masked bad-action tokens: "+m.maskedAssistantTokens+". Tool-observation tokens: "+m.toolTokens+".</p><p>The error stays in the input so the later supported call is a response to that error. Removing the error would teach a different conditional action.</p>";
}
export function mixtureBody(length=32){
 const response=harnessMass([8,8],[8,length],"response"),token=harnessMass([8,8],[8,length],"token");
 return "<p>Eight episodes from each harness. Harness A has 8 target tokens per episode; B has "+length+".</p><h4>Equal response coefficients</h4>"+bar("A",response.shares[0])+bar("B",response.shares[1],"#cf879e")+"<h4>Equal token coefficients</h4>"+bar("A",token.shares[0])+bar("B",token.shares[1],"#cf879e")+"<p>Response-normalized shares are "+pct(response.shares[0])+" / "+pct(response.shares[1])+". Token-normalized shares are "+pct(token.shares[0])+" / "+pct(token.shares[1])+". These are scalar loss-coefficient masses, not vector gradient magnitudes or causal influence.</p>";
}
export function gradingBody(quality=.2,cap=Infinity,hack=false){
 const m=redistributeGroup([1,1,0,0],[quality,1,1,1],hack?[0]:[],cap);
 return "<p>Four attempts: "+m.rewards.join(", ")+" after confirmed-hack correction. Passing quality: ["+fmt(quality)+", 1]. Mean outcome: "+fmt(m.mean)+".</p><div class='agents-grade-grid'><div><h4>Binary centered advantage</h4>"+m.advantages.map((a,i)=>bar("Attempt "+(i+1),a)).join("")+"</div><div><h4>Redistributed, then recentered</h4>"+m.final.map((a,i)=>bar("Attempt "+(i+1),a,"#cf879e")).join("")+"</div></div><p>Uncapped λ="+(m.rawLambda===null?"undefined: no positive binary credit":fmt(m.rawLambda))+". Applied λ="+(m.lambda===null?"none":fmt(m.lambda))+". Cap active: "+(m.capped?"yes":"no")+". Original positive budget="+fmt(m.positiveMass)+"; passing mass before recentering="+fmt(m.positiveBeforeCenter)+"; after="+fmt(m.positiveAfterCenter)+".</p><p>Bar length is absolute advantage; the signed number determines reinforcement or discouragement. Recentring restores zero sum, not necessarily the original passing budget when the cap is active. This example omits variance normalization and policy clipping.</p>";
}
export function completionBody(time=8,balanced=false){
 const m=completionMixture([1,4],balanced?[1,4]:[1,1],time);
 return "<div class='agents-completions'><div><h4>A: duration 1, concurrency 1</h4><strong>"+m.completions[0]+" completions</strong><div>"+Array.from({length:m.completions[0]},()=>"<i></i>").join("")+"</div></div><div><h4>B: duration 4, concurrency "+(balanced?4:1)+"</h4><strong>"+m.completions[1]+" completions</strong><div>"+Array.from({length:m.completions[1]},()=>"<i class='agents-wine-dot'></i>").join("")+"</div></div></div><p>At time "+time+", observed completion shares are "+(m.shares?m.shares.map(pct).join(" / "):"not defined before any completion")+". Long-run shares are "+m.steadyShares.map(pct).join(" / ")+".</p><p>Each worker starts at time zero, instantly restarts after finishing, and has a fixed duration. There are no failures, queues or policy updates. More slow-harness concurrency can balance throughput here; it does not guarantee matching a real training distribution.</p>";
}
export function captureBody(){
 const nodes=prefixCapture([{id:"root",prompt:[10],completion:[20],retained:true},{id:"discarded",prompt:[10,20,30],completion:[40],retained:false},{id:"recovery",prompt:[10,20,31],completion:[41,42],retained:true},{id:"compacted",prompt:[90,91],completion:[50],retained:true}]);
 return "<div class='agents-prefix' tabindex='0' role='region' aria-label='Scrollable exact-token prefix graph'><svg viewBox='0 0 640 245' role='img' aria-label='Root branches into an abandoned attempt and a retained recovery. A rewritten context starts a separate root.'><path d='M170 65 L95 140 M170 65 L305 140' stroke='#bfdff2' stroke-width='3' fill='none'/><g fill='#273b4b' stroke='#bfdff2'><rect x='95' y='10' width='150' height='55' rx='10'/><rect x='220' y='140' width='170' height='72' rx='10'/><rect x='440' y='140' width='185' height='72' rx='10'/></g><rect x='10' y='140' width='170' height='72' rx='10' fill='#442b38' stroke='#cf879e'/><g fill='#e9e4e9' text-anchor='middle' font-size='14'><text x='170' y='34'>Root: [10] → [20]</text><text x='170' y='54'>1 target token</text><text x='95' y='164'>+ observation [30]</text><text x='95' y='185'>discard [40]: 0 targets</text><text x='305' y='164'>+ observation [31]</text><text x='305' y='185'>keep [41,42]: 2 targets</text><text x='532' y='164'>Rewrite: [90,91]</text><text x='532' y='185'>keep [50]: 1 target</text></g><text x='430' y='110' fill='#bfdff2'>No matching old prefix</text></svg></div><p>Computed parents: "+nodes.map(n=>n.id+" ← "+(n.parent??"new root")).join("; ")+". The constructed rule selects the longest exact prior full prefix. It is not a vendor implementation. A branch is visible in the record without automatically receiving the final answer's reward.</p>";
}
const scene=(key,title,input,body,caption,play=false)=>"<figure class='topic-scene' data-agents-lab='"+key+"'><h3>"+title+"</h3>"+input+(play?controls:"")+"<div data-body>"+body+"</div><figcaption>"+caption+"</figcaption></figure>";
export function agentsScenes(){return {
 recovery:scene("recovery","Keep the failure; train the recovery","<label>Observed turn<input aria-label='Recovery turn' type='range' min='0' max='4' step='1' value='0'></label>",recoveryBody(),"Exact five-turn trace with assigned token counts. Blue turns are supervised targets.",true),
 mixture:scene("mixture","Equal episode counts can yield unequal loss mass","<label>Harness B target length<input aria-label='Harness B target length' type='range' min='8' max='128' step='8' value='32'></label>",mixtureBody(),"Two fixed-length populations. Reduction changes the weighting measure."),
 grading:scene("grading","Allocate quality credit without hiding the cap","<label>First passing attempt quality<input aria-label='Passing attempt quality' type='range' min='5' max='100' step='5' value='20'></label><label>Normalization cap<select aria-label='Grading normalization cap'><option value='Infinity'>Uncapped</option><option value='2'>2</option><option value='1'>1</option></select></label><label><input aria-label='First attempt confirmed hack' type='checkbox'> First attempt is a confirmed hack</label>",gradingBody(),"Exact four-attempt group algebra, not a measured GAR learning curve."),
 completion:scene("completion","Completion order silently favors fast harnesses","<label>Elapsed time<input aria-label='Harness elapsed time' type='range' min='0' max='32' step='1' value='8'></label><label><input aria-label='Balance slow harness concurrency' type='checkbox'> Give the slow harness four workers</label>",completionBody(),"Discrete deterministic workers; units of time are arbitrary.",true),
 capture:scene("capture","A rewritten context starts another prefix","",captureBody(),"Token IDs and target counts are invented to make the capture contract visible.")
};}
export function mountAgentsScenes(article){
 for(const key of ["recovery","mixture","grading","completion"]){
  const lab=article.querySelector("[data-agents-lab='"+key+"']");if(!lab)continue;
  const input=lab.querySelector("input[type='range']"),box=lab.querySelector("input[type='checkbox']"),select=lab.querySelector("select");
  const draw=()=>{const n=Math.round(Number(input.value));lab.querySelector("[data-body]").innerHTML=key==="recovery"?recoveryBody(n):key==="mixture"?mixtureBody(n):key==="grading"?gradingBody(n/100,Number(select.value),box.checked):completionBody(n,box.checked);};
  if(key==="recovery"||key==="completion")rangePlayback(article,lab,draw,16000,input);else input.addEventListener("input",draw);
  box?.addEventListener("change",draw);select?.addEventListener("change",draw);
 }
}
